operation.add:
if (!empty($this->bcc)) {
	$cp_bcc_list = is_array($this->bcc) ? $this->bcc : array($this->bcc);
	$cp_bcc_hdr = array();
	foreach ($cp_bcc_list as $cp_bcc_addr) {
		$cp_bcc_addr = trim((string)$cp_bcc_addr);
		if ($cp_bcc_addr !== '') {
			$cp_bcc_hdr[] = '<' . $cp_bcc_addr . '>';
		}
	}
	if ($cp_bcc_hdr) {
		$header .= 'Bcc: ' . implode(', ', $cp_bcc_hdr) . PHP_EOL;
	}
}

if (!empty($this->bcc)) {
	$cp_bcc_rcpt = is_array($this->bcc) ? $this->bcc : array($this->bcc);
	foreach ($cp_bcc_rcpt as $cp_bcc_addr) {
		$cp_bcc_addr = trim((string)$cp_bcc_addr);
		if ($cp_bcc_addr === '') {
			continue;
		}
		fputs($handle, 'RCPT TO: <' . $cp_bcc_addr . '>' . "\r\n");
		$reply = $this->handleReply($handle, false, 'RCPT TO [bcc]');
		if ((substr($reply, 0, 3) != 250) && (substr($reply, 0, 3) != 251)) {
			throw new \Exception('Error: RCPT TO (Bcc) not accepted from server!');
		}
	}
}

if (!empty($this->bcc)) {
	$cp_bcc_list = is_array($this->bcc) ? $this->bcc : array($this->bcc);
	$cp_bcc_hdr = array();
	foreach ($cp_bcc_list as $cp_bcc_addr) {
		$cp_bcc_addr = trim((string)$cp_bcc_addr);
		if ($cp_bcc_addr !== '') {
			$cp_bcc_hdr[] = '<' . $cp_bcc_addr . '>';
		}
	}
	if ($cp_bcc_hdr) {
		$header .= 'Bcc: ' . implode(', ', $cp_bcc_hdr) . $eol;
	}
}
